#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/device.h>

/* Get the ADC device and channel specifications from the devicetree */
static const struct adc_dt_spec adc_cfg = ADC_DT_SPEC_GET(DT_PATH(zephyr_user));

int main(void)
{
	/* Verify the ADC device is ready */
	if (!device_is_ready(adc_cfg.dev)) {
		printk("ADC device not ready\n");
		return -ENODEV;
	}

	/* Set up the ADC channel */
	if (adc_channel_setup_dt(&adc_cfg) < 0) {
		printk("Failed to configure ADC channel\n");
		return -EINVAL;
	}

	/* Sample buffer and ADC sequence */
	static int16_t buf[1];
	static const struct adc_sequence seq = {
		.channels = BIT(adc_cfg.channel_id),
		.buffer = buf,
		.buffer_size = sizeof(buf),
		.resolution = adc_cfg.resolution,
	};

	/* Main loop: read and convert to millivolts */
	while (1) {
		if (adc_read_dt(&adc_cfg, &seq) < 0) {
			printk("ADC read failed\n");
			continue;
		}

		int32_t millivolts = adc_raw_to_millivolts_dt(&adc_cfg, buf[0]);

		printk("ADC raw: %d, millivolts: %d mV\n", buf[0], millivolts);

		k_msleep(1000);
	}

	return 0;
}
